from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route('/user')
def get_user():
    user_id = request.args.get('id')

    with open('/var/www/html/static/data/users.json') as f:
        data = f.read()

    import json
    users = json.loads(data)

    user = next((u for u in users if u['id'] == user_id), None)

    if user:
        return jsonify(user)
    else:
        return jsonify({'error': 'User not found'}), 404

from flask import Flask, request
from jinja2 import Template

app = Flask(__name__)

@app.route('/list')
def list_data():
    username = request.args.get('username')
    items = request.args.get('items')

    template = Template("{{username}} has these items:{{items}}", autoescape=True)
    return template.render(username=username, items=items)
